export function lineTotal(cents: number, taxRate: number): number {
  const base = Math.round(cents);
  return base + Math.round(base * taxRate);
}

export function parseRow(line: string): string[] {
  return (line.match(/("([^"]|"")*"|[^,]*)(,|$)/g) ?? []).map((cell) =>
    cell.replace(/,$/, "").replace(/^"|"$/g, "").replace(/""/g, '"'),
  );
}

export function nextDelayMs(attempt: number, rand = Math.random): number {
  const ceiling = Math.min(2 ** attempt * 250, 30_000);
  return Math.round(ceiling * (0.5 + rand() * 0.5));
}

export function shiftEnd(startUtc: Date, hours: number, zone: string): Date {
  const local = new Date(startUtc.toLocaleString("en-US", { timeZone: zone }));
  local.setHours(local.getHours() + hours);
  return new Date(local.toISOString());
}

export function pageSlice<T>(rows: T[], page: number, size: number): T[] {
  const start = (page - 1) * size;
  return rows.slice(start, start + size);
}

export function cacheKey(parts: Record<string, string>): string {
  return Object.keys(parts)
    .sort()
    .map((name) => `${encodeURIComponent(name)}=${encodeURIComponent(parts[name] ?? "")}`)
    .join("&");
}

export function toCamel(row: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(row)) out[camel(key)] = value ?? null;
  return out;
}

export function slugify(name: string): string {
  const folded = name.normalize("NFKD").replace(/\p{Diacritic}/gu, "").toLowerCase();
  const slug = folded.replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  return slug === "" ? "job" : slug;
}

export async function runPool<T>(jobs: Array<() => Promise<T>>, cap = 8): Promise<T[]> {
  const out: T[] = new Array<T>(jobs.length);
  let next = 0;
  const worker = async (): Promise<void> => {
    while (next < jobs.length) {
      const index = next++;
      out[index] = await (jobs[index] as () => Promise<T>)();
    }
  };
  await Promise.all(Array.from({ length: Math.min(cap, jobs.length) }, worker));
  return out;
}

export function redact(line: string): string {
  return line
    .replace(/password=\S+/gi, "password=***")
    .replace(/authorization:\s*\S+/gi, "authorization: ***")
    .replace(/\b(sk|pk)-[A-Za-z0-9]{8,}\b/g, "***");
}
